module HintCounter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    input wire [7:0] m,\n    input wire [7:0] l_0,\n    input wire [7:0] l_1,\n    input wire [7:0] l_2,\n    input wire [7:0] l_3,\n    input wire [7:0] r_0,\n    input wire [7:0] r_1,\n    input wire [7:0] r_2,\n    input wire [7:0] r_3,\n    input wire type_0,\n    input wire type_1,\n    input wire type_2,\n    input wire type_3,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] COMPUTE = 2'b01;\n    localparam [1:0] DONE = 2'b10;\n    \n    reg [1:0] state;\n    reg [7:0] seq;\n    reg [2:0] hint_idx;\n    reg [31:0] count;\n    reg [7:0] max_seq;\n    \n    wire [7:0] current_l = (hint_idx == 3'd0) ? l_0 :\n                          (hint_idx == 3'd1) ? l_1 :\n                          (hint_idx == 3'd2) ? l_2 : l_3;\n    \n    wire [7:0] current_r = (hint_idx == 3'd0) ? r_0 :\n                          (hint_idx == 3'd1) ? r_1 :\n                          (hint_idx == 3'd2) ? r_2 : r_3;\n    \n    wire current_type = (hint_idx == 3'd0) ? type_0 :\n                        (hint_idx == 3'd1) ? type_1 :\n                        (hint_idx == 3'd2) ? type_2 : type_3;\n    \n    wire [8:0] full_mask = (9'd1 << current_r) - (9'd1 << (current_l - 1));\n    wire [7:0] mask = full_mask[7:0] & ((8'd1 << n) - 8'd1);\n    wire [7:0] masked_bits = seq & mask;\n    wire bits_all_0 = (masked_bits == 8'd0);\n    wire bits_all_1 = (masked_bits == mask);\n    wire hint_pass = current_type ? ~(bits_all_0 | bits_all_1) : (bits_all_0 | bits_all_1);\n    \n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            seq <= 8'd0;\n            hint_idx <= 3'd0;\n            count <= 32'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n            max_seq <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= COMPUTE;\n                        seq <= 8'd0;\n                        hint_idx <= 3'd0;\n                        count <= 32'd0;\n                        done <= 1'b0;\n                        max_seq <= (8'd1 << n) - 8'd1;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (seq > max_seq) begin\n                        state <= DONE;\n                        result <= count % 32'd1000000007;\n                        done <= 1'b1;\n                    end else if (hint_idx >= m) begin\n                        count <= count + 32'd1;\n                        seq <= seq + 8'd1;\n                        hint_idx <= 3'd0;\n                    end else if (hint_pass) begin\n                        hint_idx <= hint_idx + 3'd1;\n                    end else begin\n                        seq <= seq + 8'd1;\n                        hint_idx <= 3'd0;\n                    end\n                end\n                \n                DONE: begin\n                    // Remain in DONE until reset\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule